# Analysis panel
p=Path('app/src/AnalysisPanelV13.tsx'); s=p.read_text()
anchor="const [controlTolerance,setControlTolerance]=useState(project.settings?.displacementControlTolerance??1e-7);"
s=s.replace(anchor,anchor+"\n  const [cyclicProtocolEnabled,setCyclicProtocolEnabled]=useState(!!project.settings?.cyclicProtocolEnabled);\n  const [cyclicTargets,setCyclicTargets]=useState((project.settings?.cyclicProtocolTargets||[-.02,.02,-.04,.04,0]).map((v:any)=>String((project.settings?.displacementControlDof||'uy')==='rz'?num(v):num(v)*1000)).join(', '));\n  const [cyclicStepsPerSegment,setCyclicStepsPerSegment]=useState(project.settings?.cyclicStepsPerSegment??6);")
apply_anchor="p.settings.nonlinearControlMode=controlMode==='arc-length'?'arc-length':(controlMode==='displacement'?'displacement':'load');p.settings.displacementControlNodeId=controlNodeId||null;p.settings.displacementControlDof=['ux','uy','rz'].includes(controlDof)?controlDof:'uy';p.settings.displacementControlTarget=Number.isFinite(Number(controlTarget))&&Math.abs(Number(controlTarget))>1e-12?Number(controlTarget):-0.05;p.settings.displacementControlTolerance=Math.max(1e-10,num(controlTolerance,1e-7));"
replace=apply_anchor+"\n    const parsedTargets=String(cyclicTargets).split(/[;,\\s]+/).map(Number).filter(Number.isFinite).map(v=>controlDof==='rz'?v:v/1000);p.settings.cyclicProtocolEnabled=controlMode==='displacement'&&!!cyclicProtocolEnabled;p.settings.cyclicProtocolTargets=parsedTargets.length?parsedTargets:[-.02,.02,-.04,.04,0];p.settings.cyclicStepsPerSegment=Math.max(2,Math.min(60,Math.round(num(cyclicStepsPerSegment,6))));"
if apply_anchor not in s: raise SystemExit('Analysis apply anchor missing')
s=s.replace(apply_anchor,replace)
jsx_anchor="<div data-testid=\"pushover-control-note\" className=\"panel-note\">O padrão do cenário é escalado pelo fator <b>λ</b>, que passa a ser incógnita do sistema aumentado. Em cada incremento o solver impõe o deslocamento-alvo em {controlNodeId||'—'}/{controlDof.toUpperCase()} e resolve simultaneamente o equilíbrio global. Para rótulas de fibras, o acoplamento material embutido é obrigatório. Arc-length/Riks é uma alternativa separada quando o caminho possui ponto-limite.</div>"
cyclic_ui="<div className=\"react-card\" data-testid=\"cyclic-protocol-controls\"><label className=\"checkbox-line\"><input data-testid=\"cyclic-protocol-enabled\" type=\"checkbox\" checked={cyclicProtocolEnabled} onChange={e=>setCyclicProtocolEnabled(e.target.checked)}/><span><b>Protocolo cíclico · v0.21</b></span></label>{cyclicProtocolEnabled&&<div className=\"geometry-grid\"><label>{controlDof==='rz'?'Alvos [rad]':'Alvos [mm]'}<input data-testid=\"cyclic-protocol-targets\" value={cyclicTargets} onChange={e=>setCyclicTargets(e.target.value)}/></label><label>Passos por trecho<input data-testid=\"cyclic-steps-per-segment\" type=\"number\" min=\"2\" max=\"60\" value={cyclicStepsPerSegment} onChange={e=>setCyclicStepsPerSegment(num(e.target.value,6))}/></label></div>}<div className=\"panel-note\">Os alvos são percorridos em sequência por controle de deslocamento. Para elementos com história cíclica ativa, as variáveis internas das fibras são comprometidas somente após convergência global; tentativas rejeitadas são descartadas.</div></div>"
if jsx_anchor not in s: raise SystemExit('Analysis pushover note anchor missing')
s=s.replace(jsx_anchor,jsx_anchor+cyclic_ui)
s=s.replace("Newton–Raphson incremental · v0.19","Newton–Raphson incremental · v0.21")
s=s.replace("Continuam fora do escopo: plasticidade distribuída/cíclica, concreto não linear, contato, follower distribuída, molas nodais e recalques.","A v0.21 acrescenta plasticidade distribuída cíclica de aço por histórico incremental, Bauschinger linear e protocolos de deslocamento reversível. Continuam fora do escopo: concreto não linear, dano/fadiga, flambagem local, contato, follower distribuída, molas nodais e recalques.")
p.write_text(s)

